window.VOCAB = [{"term": "Global Value Chains (GVCs)", "meaning": "Chuỗi giá trị toàn cầu", "definition": "The worldwide network of countries and firms involved in the different stages of making a product."}, {"term": "Production Fragmentation", "meaning": "Phân mảnh sản xuất", "definition": "Splitting a production process into separate stages carried out in different locations."}, {"term": "Offshoring", "meaning": "Dịch chuyển hoạt động ra nước ngoài", "definition": "Moving a business activity to another country."}, {"term": "Outsourcing", "meaning": "Thuê ngoài / gia công thuê ngoài", "definition": "Buying goods or services from an external supplier instead of producing them yourself."}, {"term": "Vertical Specialization", "meaning": "Chuyên môn hóa theo chiều dọc", "definition": "A narrow way of measuring how much production is split across borders."}, {"term": "Trade in Value-Added (TiVA)", "meaning": "Thương mại theo giá trị gia tăng", "definition": "Tracking trade by where value was actually added, not just where goods crossed a border."}, {"term": "Spiders", "meaning": "Mô hình \"mạng nhện\" (chuỗi giá trị dạng lắp ráp không tuần tự)", "definition": "In GVC analysis, an assembly-type production process with no fixed sequence."}, {"term": "Snakes", "meaning": "Mô hình \"chuỗi rắn\" (chuỗi giá trị tuần tự)", "definition": "In GVC analysis, a production process that moves step-by-step from upstream to downstream."}, {"term": "Factoryless Goods Producers", "meaning": "Nhà sản xuất không sở hữu nhà máy", "definition": "A firm that designs and controls a product but doesn't manufacture it itself."}, {"term": "Upstreamness", "meaning": "Mức độ \"thượng nguồn\"", "definition": "How far, on average, an industry sits from the final consumer."}, {"term": "Downstreamness", "meaning": "Mức độ \"hạ nguồn\"", "definition": "How close, on average, an industry sits to the final consumer."}, {"term": "Spatial Unbundling", "meaning": "Tháo gỡ (phân tách) không gian trong sản xuất", "definition": "The historical separation of production stages that used to happen in one place."}, {"term": "Arm's-Length Transactions", "meaning": "Giao dịch độc lập (giữa các bên không liên kết)", "definition": "A deal made between two completely independent, unrelated parties."}, {"term": "Non-Tariff Barriers (NTBs)", "meaning": "Hàng rào phi thuế quan", "definition": "Government trade restrictions that are not simple import taxes."}, {"term": "Behind-the-Border (BTB) measures", "meaning": "Biện pháp \"sau biên giới\"", "definition": "Domestic regulations that affect trade even though they apply equally to everyone."}, {"term": "Trade Defense Instruments (TDIs)", "meaning": "Công cụ phòng vệ thương mại", "definition": "Legal tools a country uses to counter unfair trade practices from abroad."}, {"term": "Sanitary and Phytosanitary Measures (SPS)", "meaning": "Biện pháp kiểm dịch động, thực vật", "definition": "Rules protecting human, animal, or plant health that can also restrict trade."}, {"term": "Technical Barriers to Trade (TBT)", "meaning": "Hàng rào kỹ thuật trong thương mại", "definition": "Product standards and technical regulations that can restrict trade."}, {"term": "Structural Gravity Model", "meaning": "Mô hình trọng lực cấu trúc", "definition": "The standard economic model predicting trade flows from country size and distance."}, {"term": "Multilateral Resistance Terms", "meaning": "Thành phần \"kháng lực đa phương\"", "definition": "Parts of a gravity model capturing the average trade barriers a country faces with the rest of the world."}, {"term": "Metacoupling", "meaning": "Khung phân tích \"siêu kết nối\"", "definition": "A framework for studying human–nature connections across different geographic scales at once."}, {"term": "Intracoupling", "meaning": "Kết nối nội bộ (trong phạm vi một quốc gia/vùng)", "definition": "Interactions that happen entirely inside one country or region."}, {"term": "Pericoupling", "meaning": "Kết nối cận biên (giữa các hệ thống lân cận)", "definition": "Interactions between neighboring countries or regions."}, {"term": "Telecoupling", "meaning": "Kết nối viễn khoảng (giữa các hệ thống ở xa nhau)", "definition": "Interactions between distant, seemingly unconnected countries."}, {"term": "Pollution Haven Hypothesis", "meaning": "Giả thuyết \"thiên đường ô nhiễm\"", "definition": "The idea that dirty industries move to countries with weaker environmental rules."}, {"term": "Ecologically Unequal Exchange (EUE)", "meaning": "Trao đổi sinh thái bất bình đẳng", "definition": "The idea that rich countries offload environmental costs onto poorer trading partners."}, {"term": "Virtual Water Trade", "meaning": "Thương mại nước ảo", "definition": "The hidden water used to make goods that are then traded internationally."}, {"term": "Water Footprint", "meaning": "Dấu chân nước", "definition": "The total amount of water used, directly or indirectly, to produce what a country consumes or trades."}, {"term": "Carbon Footprint / Embodied Carbon", "meaning": "Dấu chân carbon / carbon hàm chứa", "definition": "The total greenhouse-gas emissions caused by making and transporting a traded good."}, {"term": "Price-Specie-Flow Mechanism", "meaning": "Cơ chế dòng chảy tiền kim loại theo giá", "definition": "The classical theory that gold flows automatically fix trade imbalances."}, {"term": "Say's Law", "meaning": "Định luật Say (\"cung tự tạo ra cầu\")", "definition": "The classical claim that supply automatically creates its own demand."}, {"term": "Marshall-Lerner Condition", "meaning": "Điều kiện Marshall–Lerner", "definition": "The rule for when a currency devaluation actually improves the trade balance."}, {"term": "Kaldor Paradox", "meaning": "Nghịch lý Kaldor", "definition": "The puzzling finding that rising labor costs can go along with rising export success."}, {"term": "Verdoorn's Law", "meaning": "Định luật Verdoorn", "definition": "The idea that faster manufacturing growth causes faster productivity growth."}, {"term": "Polarisation Process / Cumulative Causation", "meaning": "Quá trình phân cực / Nhân quả tích lũy", "definition": "A self-reinforcing spiral where richer regions keep pulling ahead of poorer ones."}, {"term": "Comparative Advantage", "meaning": "Lợi thế so sánh", "definition": "The idea that countries should specialize in what they produce relatively most efficiently, not necessarily best."}, {"term": "Absolute Advantage", "meaning": "Lợi thế tuyệt đối", "definition": "Being able to produce more of a good than another country using the same resources."}, {"term": "Factor Price Equalization Theorem", "meaning": "Định lý cân bằng giá yếu tố sản xuất", "definition": "The theorem that free trade should make wages and returns to capital converge across countries."}, {"term": "Opportunity Costs", "meaning": "Chi phí cơ hội", "definition": "What you give up by choosing one option over the next-best alternative."}, {"term": "Production Possibility Frontier", "meaning": "Đường giới hạn khả năng sản xuất", "definition": "The graph line showing the maximum combinations of two goods an economy can produce."}, {"term": "Social Indifference Curves", "meaning": "Đường bàng quan xã hội", "definition": "Curves showing combinations of goods that give a whole society equal satisfaction."}, {"term": "Heckscher-Ohlin Model", "meaning": "Mô hình Heckscher-Ohlin", "definition": "The trade theory explaining trade patterns through differences in factor endowments."}, {"term": "Terms of Trade", "meaning": "Tỷ lệ trao đổi thương mại (tỷ giá thương mại)", "definition": "The rate at which a country's exports exchange for its imports."}, {"term": "Trade Liberalization", "meaning": "Tự do hóa thương mại", "definition": "Reducing government barriers to trade between countries."}, {"term": "Free Trade Agreement (FTA) Depth", "meaning": "Mức độ \"sâu\" của hiệp định thương mại tự do", "definition": "How much a trade agreement covers beyond simple tariff cuts."}, {"term": "Intra-Industry Trade", "meaning": "Thương mại nội ngành", "definition": "Trading similar goods within the same industry, in both directions."}, {"term": "Methuen Treaty", "meaning": "Hiệp ước Methuen", "definition": "The 1703 treaty that locked England and Portugal into a preferential wool-for-wine trade."}];